# Analyze repository structures
def analyze_repo_structure(repo_path):
    """Analyze repository structure and extract key information"""
    analysis = {
        'name': os.path.basename(repo_path),
        'files': [],
        'package_json': None,
        'vercel_json': None,
        'env_example': None,
        'api_endpoints': [],
        'frontend_files': [],
        'database_files': [],
        'directories': []
    }

    for root, dirs, files in os.walk(repo_path):
        # Skip .git directory
        if '.git' in root:
            continue

        rel_root = os.path.relpath(root, repo_path)
        if rel_root == '.':
            rel_root = ''

        # Track directories
        for d in dirs:
            if d != '.git':
                analysis['directories'].append(os.path.join(rel_root, d) if rel_root else d)

        # Analyze files
        for file in files:
            file_path = os.path.join(rel_root, file) if rel_root else file
            analysis['files'].append(file_path)

            # Check for important files
            if file == 'package.json':
                try:
                    with open(os.path.join(root, file), 'r') as f:
                        analysis['package_json'] = json.load(f)
                except:
                    pass

            elif file == 'vercel.json':
                try:
                    with open(os.path.join(root, file), 'r') as f:
                        analysis['vercel_json'] = json.load(f)
                except:
                    pass

            elif file == '.env.example' or file == '.env.local.example':
                try:
                    with open(os.path.join(root, file), 'r') as f:
                        analysis['env_example'] = f.read()
                except:
                    pass

            # Identify API endpoints
            elif file.endswith('.js') and ('api' in root.lower() or 'endpoint' in root.lower()):
                analysis['api_endpoints'].append(file_path)

            # Identify frontend files
            elif file.endswith(('.jsx', '.tsx', '.js', '.ts')) and any(keyword in root.lower() for keyword in ['component', 'page', 'src', 'app']):
                analysis['frontend_files'].append(file_path)

            # Identify database files
            elif file.endswith(('.sql', '.db', '.sqlite')):
                analysis['database_files'].append(file_path)

    return analysis

