    # Backend main API file
    backend_index_js = '''import express from 'express'
import cors from 'cors'
import helmet from 'helmet'
import rateLimit from 'express-rate-limit'
import morgan from 'morgan'
import dotenv from 'dotenv'

// Import agent routes
import sentimentAgent from './agents/sentiment-agent.js'
import recommendationAgent from './agents/recommendation-agent.js'
import performanceMonitor from './agents/performance-monitor.js'
import agentFactory from './agents/agent-factory.js'
import healthCheck from './agents/health.js'

dotenv.config()

const app = express()
const PORT = process.env.PORT || 3001

// Security middleware
app.use(helmet())

// CORS configuration
const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['http://localhost:3000'],
  credentials: true,
  optionsSuccessStatus: 200
}
app.use(cors(corsOptions))

// Rate limiting
const limiter = rateLimit({
  windowMs: parseInt(process.env.RATE_LIMIT_WINDOW_MS) || 15 * 60 * 1000,
  max: parseInt(process.env.RATE_LIMIT_MAX_REQUESTS) || 100,
  message: {
    error: 'Too many requests from this IP, please try again later.'
  }
})
app.use('/api/', limiter)

// Logging
app.use(morgan('combined'))

// Body parsing middleware
app.use(express.json({ limit: '10mb' }))
app.use(express.urlencoded({ extended: true }))

// API routes
app.use('/api/sentiment-agent', sentimentAgent)
app.use('/api/recommendation-agent', recommendationAgent)
app.use('/api/performance-monitor', performanceMonitor)
app.use('/api/agent-factory', agentFactory)
app.use('/api/health', healthCheck)

// Root endpoint
app.get('/', (req, res) => {
  res.json({
    message: 'FMAA Backend API',
    version: '1.0.0',
    status: 'active',
    endpoints: [
      '/api/sentiment-agent',
      '/api/recommendation-agent', 
      '/api/performance-monitor',
      '/api/agent-factory',
      '/api/health'
    ]
  })
})

// Error handling middleware
app.use((err, req, res, next) => {
  console.error(err.stack)
  res.status(500).json({
    error: 'Something went wrong!',
    message: process.env.NODE_ENV === 'development' ? err.message : 'Internal server error'
  })
})

// 404 handler
app.use('*', (req, res) => {
  res.status(404).json({
    error: 'Route not found',
    path: req.originalUrl
  })
})

// Start server
if (process.env.NODE_ENV !== 'test') {
  app.listen(PORT, () => {
    console.log(`🚀 FMAA Backend running on port ${PORT}`)
    console.log(`📡 API endpoints available at http://localhost:${PORT}/api/`)
  })
}

export default app
